public sealed class Editor:Window {
 readonly string storage=System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ChaseLab_MM");
 readonly string bridge=System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ChaseLab_MM","bridge-win-demo");
 Project project;int sequence,edit,step;double phase,beats;bool playing,connected,dirty,painting,paintValue,rebuilding;volatile bool writing;double arenaTempo;double arenaTempoAt=-100;DateTime modified=DateTime.UtcNow;string? xmlPath;DateTime xmlStamp;readonly string session=Guid.NewGuid().ToString();long frame;readonly Stopwatch clock=Stopwatch.StartNew();double last;
 readonly StackPanel top=new(){Orientation=Orientation.Horizontal};readonly ListBox sequences=new(){MinWidth=160};readonly Canvas canvas=new(){Background=Brushes.Black,ClipToBounds=true,Height=330};readonly StackPanel matrix=new();readonly TextBlock status=new(){Margin=new Thickness(8),Foreground=Brushes.LightGray};readonly ComboBox envelope=new(){Width=110};readonly TextBox bpm=new(){Width=55,Text="120"};readonly CheckBox hostBpm=new(){Content="BPM Arena",Margin=new Thickness(8)};readonly CheckBox follow=new(){Content="Seguir XML guardado",Margin=new Thickness(8)};readonly TextBlock position=new(){Margin=new Thickness(8)};readonly ScaleTransform zoom=new(1,1);readonly TranslateTransform pan=new();Point? panStart;readonly List<Polygon> shapes=new();readonly List<(Button button,int row,int col)> cells=new();readonly DispatcherTimer timer=new(){Interval=TimeSpan.FromMilliseconds(33)};readonly Stack<string> undo=new();double poll;
 public Editor(){
  Title="ChaseLab_MM — Windows demo 0.1";Width=1200;Height=820;MinWidth=860;MinHeight=600;Background=new SolidColorBrush(Color.FromRgb(12,17,22));Foreground=Brushes.White;
  var root=new DockPanel();Content=root;DockPanel.SetDock(top,Dock.Top);root.Children.Add(top);top.Margin=new Thickness(8);DockPanel.SetDock(status,Dock.Bottom);root.Children.Add(status);
  Button Add(string name,Action action){var b=Button(name,()=>Guard(action));top.Children.Add(b);return b;}
  Add("Abrir…",Open);Add("Guardar…",Save);Add("Importar XML…",Import);Add("▶ / Pausa",()=>{playing=!playing;});Add("↤",()=>{beats=0;step=0;phase=0;});Add("Conectar Arena",()=>{connected=!connected;});Add("Instalar Player…",Install);Add("Diagnóstico…",Diagnostics);
  var left=new DockPanel{Width=175};DockPanel.SetDock(left,Dock.Left);root.Children.Add(left);var seqButtons=new StackPanel{Orientation=Orientation.Horizontal};DockPanel.SetDock(seqButtons,Dock.Bottom);left.Children.Add(seqButtons);seqButtons.Children.Add(Button("+ Secuencia",()=>Change(()=>{if(project.Sequences.Count>=128)return;var copy=project.Sequences[sequence]!.DeepClone();copy!["id"]=Guid.NewGuid().ToString();copy["name"]=$"Chase {project.Sequences.Count+1:00}";project.Sequences.Add(copy);sequence=project.Sequences.Count-1;beats=0;})));left.Children.Add(sequences);sequences.SelectionChanged+=(_,_)=>{if(!rebuilding&&sequences.SelectedIndex>=0){sequence=sequences.SelectedIndex;edit=0;beats=0;Rebuild();}};
  var body=new DockPanel{Margin=new Thickness(8)};root.Children.Add(body);var transport=new WrapPanel();DockPanel.SetDock(transport,Dock.Top);body.Children.Add(transport);transport.Children.Add(new TextBlock{Text="BPM",Margin=new Thickness(5)});transport.Children.Add(bpm);bpm.LostFocus+=(_,_)=>Guard(()=>{if(double.TryParse(bpm.Text,out var v))Change(()=>project.Bpm=v);});transport.Children.Add(hostBpm);foreach(var s in new[]{"Corte","Fade out","Pulso","Bézier"})envelope.Items.Add(s);envelope.SelectionChanged+=(_,_)=>{if(envelope.SelectedItem is string s&&s!=project.Envelope)Guard(()=>Change(()=>{if(s=="Bézier"&&project.Data["bezier"]==null)throw new InvalidOperationException("Abre un proyecto Mac con curva Bézier; esta demo la reproduce pero aún no permite dibujarla.");project.Envelope=s;}));};transport.Children.Add(envelope);transport.Children.Add(follow);transport.Children.Add(Button("Ajustar",()=>{zoom.ScaleX=zoom.ScaleY=1;pan.X=pan.Y=0;Draw();}));transport.Children.Add(position);
  var preview=new Border{Child=canvas,Height=330,ClipToBounds=true,Margin=new Thickness(0,8,0,8)};DockPanel.SetDock(preview,Dock.Top);body.Children.Add(preview);canvas.SizeChanged+=(_,_)=>Draw();canvas.MouseWheel+=(_,e)=>{double z=Math.Clamp(zoom.ScaleX*(e.Delta>0?1.15:1/1.15),.25,8);zoom.ScaleX=zoom.ScaleY=z;Draw();};canvas.MouseDown+=(_,e)=>{if(e.ChangedButton==MouseButton.Middle){panStart=e.GetPosition(canvas);canvas.CaptureMouse();canvas.Cursor=Cursors.Hand;}};canvas.MouseMove+=(_,e)=>{if(panStart is Point p&&e.MiddleButton==MouseButtonState.Pressed){var n=e.GetPosition(canvas);pan.X+=n.X-p.X;pan.Y+=n.Y-p.Y;panStart=n;Draw();}};canvas.MouseUp+=(_,e)=>{if(e.ChangedButton==MouseButton.Middle){panStart=null;canvas.ReleaseMouseCapture();canvas.Cursor=Cursors.Arrow;}};
  var controls=new WrapPanel();DockPanel.SetDock(controls,Dock.Top);body.Children.Add(controls);controls.Children.Add(Button("− Paso",()=>Change(()=>{project.Resize(sequence,project.Count(sequence)-1);edit=Math.Min(edit,project.Count(sequence)-1);beats=0;})));controls.Children.Add(Button("+ Paso",()=>Change(()=>project.Resize(sequence,project.Count(sequence)+1))));controls.Children.Add(Button("Copiar paso",()=>{Clipboard.SetText(new JsonObject{["chaselabStep"]=true,["values"]=new JsonArray(Enumerable.Range(0,project.Slices.Count).Select(r=>JsonValue.Create(project.Cell(sequence,r,edit))).ToArray()),["duration"]=project.Weight(sequence,edit)}.ToJsonString());}));controls.Children.Add(Button("Pegar paso",()=>Guard(()=>{var data=JsonNode.Parse(Clipboard.GetText())!;if(data["chaselabStep"]?.GetValue<bool>()!=true||data["values"]!.AsArray().Count!=project.Slices.Count)throw new InvalidDataException("El paso no coincide con los slices.");Change(()=>{for(int r=0;r<project.Slices.Count;r++)project.SetCell(sequence,r,edit,data["values"]![r]!.GetValue<bool>());project.SetWeight(sequence,edit,data["duration"]!.GetValue<double>());});})));foreach(double w in new[]{.25,.5,1d,2d,4d})controls.Children.Add(Button($"{w}×",()=>Change(()=>project.SetWeight(sequence,edit,w))));controls.Children.Add(Button("Chase",()=>Change(()=>{for(int r=0;r<project.Slices.Count;r++)for(int c=0;c<project.Count(sequence);c++)project.SetCell(sequence,r,c,c%project.Slices.Count==r);})));controls.Children.Add(Button("Deshacer",Undo));body.Children.Add(new ScrollViewer{Content=matrix,HorizontalScrollBarVisibility=ScrollBarVisibility.Auto,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});
  project=Project.Read(System.IO.Path.Combine(AppContext.BaseDirectory,"demo.chaselab"));Directory.CreateDirectory(storage);var recovery=System.IO.Path.Combine(storage,"recovery.chaselab");if(File.Exists(recovery))try{project=Project.Read(recovery);}catch(Exception e){status.Text="Recuperación inválida; conservada. "+e.Message;}
  PreviewMouseLeftButtonUp+=(_,_)=>painting=false;Deactivated+=(_,_)=>painting=false;Closing+=(_,e)=>{try{Recover();connected=false;Send();}catch(Exception ex){if(MessageBox.Show("No se pudo guardar la recuperación: "+ex.Message+"\n¿Cerrar de todos modos?","ChaseLab_MM",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)e.Cancel=true;}};
  Rebuild();timer.Tick+=(_,_)=>Guard(Tick);timer.Start();
 }
 static Button Button(string name,Action action){var b=new Button{Content=name,Margin=new Thickness(3),Padding=new Thickness(8,5,8,5),Background=new SolidColorBrush(Color.FromRgb(33,49,53)),Foreground=Brushes.White};b.Click+=(_,_)=>action();return b;}
 void Guard(Action a){try{a();}catch(Exception e){status.Text=e.Message;File.AppendAllText(System.IO.Path.Combine(storage,"diagnostic.log"),DateTime.UtcNow.ToString("O")+" "+e+Environment.NewLine);}}
 void Change(Action a){string before=project.Data.ToJsonString();try{a();project.Validate();undo.Push(before);dirty=true;modified=DateTime.UtcNow;Rebuild();}catch{project=new Project(JsonNode.Parse(before)!.AsObject());Rebuild();throw;}}
 void Undo(){if(undo.Count==0)return;project=new Project(JsonNode.Parse(undo.Pop())!.AsObject());sequence=Math.Min(sequence,project.Sequences.Count-1);edit=0;beats=0;dirty=true;modified=DateTime.UtcNow;Rebuild();}
 void Open(){var d=new OpenFileDialog{Filter="Proyecto ChaseLab|*.chaselab"};if(d.ShowDialog()!=true)return;var p=Project.Read(d.FileName);Recover();project=p;sequence=edit=step=0;beats=0;playing=false;xmlPath=null;undo.Clear();dirty=true;modified=DateTime.UtcNow;Rebuild();}
 void Save(){var d=new SaveFileDialog{Filter="Proyecto ChaseLab|*.chaselab",FileName="Proyecto-Windows.chaselab"};if(d.ShowDialog()==true){project.Save(d.FileName);Recover();status.Text="Proyecto guardado.";}}
 void Import(){var d=new OpenFileDialog{Filter="Advanced Output XML|*.xml"};if(d.ShowDialog()!=true)return;var p=Project.ImportXml(d.FileName);if(MessageBox.Show("La importación crea una secuencia vacía. Se guarda una copia del proyecto actual. ¿Continuar?","Importar",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;project.Save(System.IO.Path.Combine(storage,"antes-importar-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmssfff")+".chaselab"));Change(()=>{project=p;sequence=edit=step=0;beats=0;});xmlPath=d.FileName;xmlStamp=File.GetLastWriteTimeUtc(xmlPath);}
 void Rebuild(){rebuilding=true;sequence=Math.Clamp(sequence,0,project.Sequences.Count-1);edit=Math.Clamp(edit,0,project.Count(sequence)-1);step=Math.Clamp(step,0,project.Count(sequence)-1);sequences.Items.Clear();foreach(var s in project.Sequences)sequences.Items.Add(s!["name"]!.GetValue<string>());sequences.SelectedIndex=sequence;bpm.Text=project.Bpm.ToString("0.##");envelope.SelectedItem=project.Envelope;matrix.Children.Clear();cells.Clear();var header=new StackPanel{Orientation=Orientation.Horizontal};header.Children.Add(new TextBlock{Text="Slice / Paso",Width=145});for(int c=0;c<project.Count(sequence);c++){int col=c;header.Children.Add(Button($"{c+1:00}\n{project.Weight(sequence,c)}×",()=>{edit=col;Update();}));}matrix.Children.Add(header);for(int r=0;r<project.Slices.Count;r++){int row=r;var line=new StackPanel{Orientation=Orientation.Horizontal};line.Children.Add(new TextBlock{Text=project.Slices[r]!["name"]!.GetValue<string>(),Width=145,VerticalAlignment=VerticalAlignment.Center});for(int c=0;c<project.Count(sequence);c++){int col=c;var b=Button(" ",()=>{});b.Width=48;b.Height=30;b.PreviewMouseLeftButtonDown+=(_,e)=>{undo.Push(project.Data.ToJsonString());painting=true;paintValue=!project.Cell(sequence,row,col);Paint(row,col);e.Handled=true;};b.MouseEnter+=(_,_)=>{if(painting&&Mouse.LeftButton==MouseButtonState.Pressed)Paint(row,col);};line.Children.Add(b);cells.Add((b,row,col));}matrix.Children.Add(line);}Draw();Update();rebuilding=false;}
 void Paint(int r,int c){project.SetCell(sequence,r,c,paintValue);dirty=true;modified=DateTime.UtcNow;Update();}
 void Draw(){canvas.Children.Clear();shapes.Clear();double scale=Math.Min(Math.Max(1,canvas.ActualWidth)/project.Width,canvas.Height/project.Height)*zoom.ScaleX;foreach(var s in project.Slices){var polygon=new Polygon{Stroke=Brushes.Gray,StrokeThickness=1};foreach(var p in s!["points"]!.AsArray())polygon.Points.Add(new Point(p!["x"]!.GetValue<double>()*scale+pan.X,p["y"]!.GetValue<double>()*scale+pan.Y));int row=shapes.Count;polygon.MouseLeftButtonDown+=(_,e)=>{undo.Push(project.Data.ToJsonString());painting=true;paintValue=!project.Cell(sequence,row,edit);Paint(row,edit);e.Handled=true;};polygon.MouseEnter+=(_,_)=>{if(painting&&Mouse.LeftButton==MouseButtonState.Pressed)Paint(row,edit);};canvas.Children.Add(polygon);shapes.Add(polygon);}Update();}
 void Update(){int c=playing?step:edit;for(int r=0;r<shapes.Count;r++)shapes[r].Fill=project.Cell(sequence,r,c)?new SolidColorBrush(Color.FromArgb((byte)(80+175*(playing?project.Level(phase):1)),65,230,190)):new SolidColorBrush(Color.FromRgb(17,24,29));foreach(var item in cells){item.button.Background=project.Cell(sequence,item.row,item.col)?Brushes.MediumAquamarine:new SolidColorBrush(Color.FromRgb(33,39,44));item.button.BorderBrush=item.col==(playing?step:edit)?Brushes.Orange:Brushes.DimGray;}position.Text=$"{step+1:00}/{project.Count(sequence):00} · edición {edit+1}";}
 void Recover(){if(!dirty)return;project.Save(System.IO.Path.Combine(storage,"recovery.chaselab"));dirty=false;}
 void Tick(){double now=clock.Elapsed.TotalSeconds,dt=Math.Min(.2,now-last);last=now;double tempo=project.Bpm;if(hostBpm.IsChecked==true&&now-arenaTempoAt<2&&arenaTempo>=20&&arenaTempo<=300)tempo=arenaTempo;if(now-poll>.5){poll=now;string ack=System.IO.Path.Combine(bridge,"receiver.json");if(connected&&File.Exists(ack))try{var data=JsonNode.Parse(File.ReadAllText(ack))!;double age=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()/1000d-data["time"]!.GetValue<double>();status.Text=age<2?"Player activo · "+data["width"]+" × "+data["height"]:"Esperando Player en Arena…";if(hostBpm.IsChecked==true&&age<2){var b=data["bpm"]!.GetValue<double>();if(b>=20&&b<=300){arenaTempo=b;arenaTempoAt=now;tempo=b;}}}catch(IOException){}if(follow.IsChecked==true&&xmlPath!=null&&File.GetLastWriteTimeUtc(xmlPath)!=xmlStamp){var fresh=Project.ImportXml(xmlPath);if(fresh.Slices.Count!=project.Slices.Count)throw new InvalidOperationException("El número de slices cambió. Importa el XML de nuevo para evitar reasignar tus pasos.");Change(()=>{project.Data["width"]=fresh.Width;project.Data["height"]=fresh.Height;for(int r=0;r<fresh.Slices.Count;r++){if(project.Slices[r]!["name"]!.GetValue<string>()!=fresh.Slices[r]!["name"]!.GetValue<string>())throw new InvalidOperationException("Cambió el orden/nombre de slices; importa de nuevo.");project.Slices[r]!["points"]=fresh.Slices[r]!["points"]!.DeepClone();}});xmlStamp=File.GetLastWriteTimeUtc(xmlPath);}}if(playing){beats+=dt*tempo/60;(step,phase)=project.Position(sequence,beats);}if(dirty&&(DateTime.UtcNow-modified).TotalSeconds>1)Recover();Update();if(connected)Send();}
 void Send(){if(writing)return;int c=playing?step:edit;var polys=new JsonArray();for(int r=0;r<project.Slices.Count;r++)if(project.Cell(sequence,r,c)){var points=new JsonArray();foreach(var p in project.Slices[r]!["points"]!.AsArray())points.Add(new JsonArray(JsonValue.Create(2*p!["x"]!.GetValue<double>()/project.Width-1),JsonValue.Create(1-2*p["y"]!.GetValue<double>()/project.Height)));polys.Add(points);}string text=new JsonObject{["version"]=1,["session"]=session,["sequence"]=++frame,["time"]=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()/1000d,["enabled"]=connected,["intensity"]=playing?project.Level(phase):1,["polygons"]=polys,["width"]=project.Width,["height"]=project.Height}.ToJsonString();writing=true;_=System.Threading.Tasks.Task.Run(()=>{try{Project.AtomicWrite(System.IO.Path.Combine(bridge,"frame.json"),text);}catch(Exception e){Dispatcher.Invoke(()=>status.Text="Error de conexión: "+e.Message);}finally{writing=false;}});}
 void Install(){var d=new OpenFolderDialog{Title="Selecciona la carpeta Extra Effects configurada en Arena"};if(d.ShowDialog()!=true)return;var source=System.IO.Path.Combine(AppContext.BaseDirectory,"Plugins","CLPlayerWinDemo_MM.dll");if(!File.Exists(source))throw new FileNotFoundException("Falta el Player en esta compilación.");string target=System.IO.Path.Combine(d.FolderName,"CLPlayerWinDemo_MM.dll");if(File.Exists(target)){string backup=System.IO.Path.Combine(storage,"plugin-backups",DateTime.UtcNow.ToString("yyyyMMdd-HHmmssfff"));Directory.CreateDirectory(backup);File.Copy(target,System.IO.Path.Combine(backup,"CLPlayerWinDemo_MM.dll"));}File.Copy(source,target,true);Project.AtomicWrite(System.IO.Path.Combine(storage,"installed-plugin.txt"),target);status.Text="Player instalado. Reinicia Arena y busca CL Win Demo_MM.";}
 void Diagnostics(){var d=new SaveFileDialog{Filter="Informe|*.txt",FileName="ChaseLab-diagnostico.txt"};if(d.ShowDialog()!=true)return;File.WriteAllText(d.FileName,$"ChaseLab_MM Windows demo 0.1\nSistema: {Environment.OSVersion}\n64 bits: {Environment.Is64BitProcess}\nMontaje: {project.Width}x{project.Height}, {project.Slices.Count} slices\nConexión: {connected}\nEstado: {status.Text}\n"+(File.Exists(System.IO.Path.Combine(storage,"diagnostic.log"))?File.ReadAllText(System.IO.Path.Combine(storage,"diagnostic.log")):""));}
}
